"""
Version information for the Kalinka server.

Two distinct, unrelated versions live here:

* The **package version** (:func:`get_version`) is generated by setuptools_scm
  from the ``kalinka-v*`` git tag and written to ``_version.py`` at build time.
* The **REST/WS API version** (:data:`REST_API_VERSION` /
  :func:`get_rest_api_version`) is the client-facing HTTP/WebSocket contract
  version. It is hardcoded and bumped by hand when that API changes — it is not
  derived from git or the package version. It is exposed via ``/server/version``
  and mDNS discovery so clients (e.g. the frontend app) can check compatibility.
  (Distinct from ``kalinka_plugin_sdk.__version__``, the server↔plugin
  contract, which the plugins' ``kalinka-plugin-sdk`` pins gate at install and
  their ``REQUIRES_SDK`` specifiers at load.)
"""

# Written by setuptools_scm at build time; absent only in an unbuilt source tree.
try:
    from ._version import version as __version__
except ImportError:
    __version__ = None


def get_version() -> str:
    """Return the package version (``X.Y.Z`` or a ``X.Y.Z.devN+…`` dev form).

    Comes from ``_version.py`` (setuptools_scm / the ``kalinka-v*`` tag). Falls
    back to ``"0.0.0"`` only when run from a source tree that was never built.
    """
    if __version__ and __version__ != "0.0.0+unknown":
        return __version__
    return "0.0.0"


# Client-facing REST/WebSocket API contract version. Bump deliberately when the
# client API changes; independent of the package version above. Distinct from
# kalinka_plugin_sdk.__version__ (the server<->plugin SDK contract).
# 0.2: playback moved to renderers — output selection lives behind /renderer/*,
# and the built-in local-alsa device is gone.
# 0.3: /queue/ws reports the renderer topology — renderers_changed and
# current_renderer_changed events, and the matching replay state fields.
# 0.4: playback state carries the output device (audio_info.output) and the
# device volume names the backend it is applied by.
# 0.5: renderer records say whether this Core can drive them (compatible)
# and whether they can install a release of themselves (upgrade_supported),
# which POST /renderer/{id}/upgrade asks them to do; playback state names
# the URL the renderer is fetching (stream_url).
# 0.6: search is asked one source at a time — `sources` is required on
# /search/matches and /ai_search, /ai_search takes a single source and no
# longer pages, and module records name the optional calls they answer
# (capabilities).
# 0.7: GET /server/config never carries a credential (a password-widget
# field): `values` omits it, `secrets_set` names the ones holding a value,
# and the schema gives such a field no default. /server/logs/export prepares
# an archive of the server's recent logs, which /server/logs/export/download
# serves. A config value may be a list of records (localfiles'
# music_sources), described in a module's or section's `collections`: its
# credentials are left out of `values` and named in `secrets_set` by the
# entry's id (`<path>.<id>.<field>`), and writing the list back without one
# keeps it while the entry is for the same server and user. An entry that now
# names another server or user, or is of another kind, draws an error at the
# credential it left out, in the dry run and the save alike, and must send it
# again. A successful PUT /server/config returns the resulting `secrets_set`.
# A collection's `replaces` names the older fields it stands for, which a
# client showing it hides. localfiles' music_folders is its local sources'
# folders; writing either list updates the other. A /server/modules entry
# carries the module's `icon` (a material icon name, or null), which a client
# draws in place of its letter badge.
# 0.8: who drives the output is `playback_control`: in the /queue/ws and
# /queue/events replay, in playback_control_changed (sent ahead of the
# state_changed it explains), and from GET /queue/control. Its mode is "queue"
# while the play queue plays, or "exclusive" with the plugin_id and title
# ("Qobuz Connect") of an input plugin that took the renderer to play outside
# the queue, as a Connect receiver does. Under "exclusive" the queue plays
# nothing and keeps its contents; state_changed and GET /queue/state describe
# the plugin's playback, with current_track the plugin's and index null. pause,
# seek, next and prev go to the plugin; play gives the renderer back to the
# queue and plays; stop gives it back without playing. Queue edits and
# set_playback_mode still apply to the queue. PUT /renderer/active moves the
# plugin's playback, which carries on where it had reached; the speaker test
# ends it.
# 0.9: read-only /server/plugins inventory separates installation origin,
# catalog identity verification and update eligibility. Public HTTPS catalogs
# are browsable with metadata-only host compatibility checks; signature
# verification and installation remain unavailable. /server/version advertises
# the implemented capabilities.
# 0.10: a settings field may be `readonly` without being `dynamic`; PUT
# /server/config refuses such a path with 400. base_config.server.demo_mode
# marks a public demo server: it answers every write outside /queue/* and PUT
# /device/set_volume, the settings dry run included, with 403
# {"detail": {"code": "demo_read_only", "message"}}, refuses /renderer/ws,
# reports upgrade_supported false, carries a General-page banner, and plays
# through the simulated renderer `demo-output`, which reports a length and no
# format. It answers a POST /queue/add past its queue limit with 409
# `demo_queue_full`, and a visitor's changes past its rate limit with 429
# `demo_rate_limited` and Retry-After.
# 0.11: /renderer/list reports `local`, proved by the optional machine identity
# in renderer Hello. A manual server upgrade vacates busy renderers, reports
# STOPPED without a playback fault, and answers `upgrading` while their installs
# finish. Core waits for confirmed target versions before starting its installer;
# the packaged renderer on its own host is covered by that installer. Refusals
# name the renderer and reason. Automatic upgrades still defer busy renderers.
# Also 0.11: a catalog whose preview type is `folder` is a folder of a file-backed
# source, listing its subfolders and then the tracks directly in it; adding
# one takes every track below it, subfolders included, in the order the
# folders list them. My Library is now such a catalog, `files`:
# the music sources, or the one source's folders, under its playlists. A
# second card, `recent`, lists the newest albums and singles. The per-kind
# shelves are no longer listed, though their catalogs still answer. POST
# /queue/add refuses an add that would take the queue past 1000 tracks with
# 409 {"detail": {"code": "queue_full", "message"}}, adding nothing.
# 0.12: POST /queue/replace takes the body /queue/add takes, without an index,
# and replaces the queue with those tracks in one request. Only the new tracks
# count against the queue limit; past it the answer is 409 with /queue/add's
# code (`queue_full`, or `demo_queue_full` on a demo server) but a message of
# its own, which does not suggest clearing the queue, and the queue is left as
# it was. Ids that come to no tracks, an empty album or folder or ids no
# source still has, are answered 422 {"detail": {"code": "no_tracks",
# "message"}}, also leaving the queue as it was. A server before 0.12 answers
# the route with 405 from its browser-player mount at "/", or with 404 where it
# has no such mount.
# 0.13: optional packages install from wheels only. A failed entry in GET
# /server/optional_packages' last_install results whose package has no wheel
# for the server's Python and architecture carries a `reason` naming all three.
# 0.14: PlaybackControl carries `seekable`, false while the plugin holding the
# output cannot seek, as AirPlay cannot; clients then offer no position
# control, and a seek sent anyway is dropped. Also 0.14: a Debian-packaged
# server installs, updates and removes catalog plugins. /server/version's
# plugin_management.installation and update_checks are true where it can;
# then POST /server/plugins/{id}/install, /update and /uninstall answer 202
# {"status": "restarting", ...} and the server restarts to carry the
# operation out, so a client follows it as it follows PUT /server/restart.
# Refusals carry {"detail": {"code", "message"}}: 404 unknown_plugin; 409
# bundle_managed, already_installed, not_installed, incompatible, up_to_date,
# unsupported_package, operation_in_progress; 500 restart_failed; 503
# installer_unavailable, catalog_unavailable.
# GET /server/plugins/updates answers {"status": "available", "updates":
# [{plugin_id, distribution, version, installed_version}]} for installed
# packages with a newer compatible release, by dpkg's ordering; GET
# /server/plugins reports the helper's record of the last operation as
# `last_operation`.
# 0.15: two plugins may offer the same optional package, as Jamendo and My
# Library both offer onnxruntime and tokenizers. GET /server/optional_packages
# still lists it once, with the first plugin's plugin_id, description and
# pip_spec; each package's `offered_by`, [{plugin_id, description}] in load
# order, names every plugin that offers it and what for. Also 0.15: a package
# with no wheel for the server's architecture, as onnxruntime on 32-bit ARM,
# is left out of GET /server/optional_packages, and PUT /server/restart
# refuses it in `install` with the 400 an unknown key gets.
# 0.16: POST /indexer/rescan requests the localfiles librarian's normal check.
# GET /indexer/status includes scan activity and the last completed check time.
# 0.17: a module's `capabilities` follow its own settings: a source whose AI
# search is switched off no longer lists `ai_search`. Plugin settings apply on
# restart, so the list changes only then.
# 0.18: a module whose browse root leads to catalogs a client may offer on its
# home screen lists `catalogs` among its `capabilities`; nothing infers it from
# browsing, so a receiver lists none. GET /browse pages the source roots by
# `offset` and `limit`, where it listed every source whatever was asked.
# 0.19: POST /renderer/{id}/upgrade stops a playback session on the renderer, a
# paused one included, as PUT /server/upgrade does, where it answered 409;
# clients see STOPPED without a fault. Before stopping anything it still
# answers 409 for a renderer already upgrading, one that cannot install a
# release of itself, or one playing that is already on the latest release. A
# renderer that refuses (409 "<name> refused: ..."), goes away (404) or does
# not answer (504) once its session is stopped is left stopped.
# Also 0.19: /queue/ws and /queue/events report the module listing. Their
# replay state carries `modules`, {input_modules, devices} as GET
# /server/modules answers, and a modules_changed event carries `input_modules`
# and `devices` whenever a health check, every 10 s, finds that a module's
# state, error_message or missing_packages moved; one that finds nothing new
# sends nothing. GET /server/modules answers what the last check found instead
# of asking every plugin again, so a change shows there within the same 10 s;
# a PUT /server/config to a module or device publishes before it answers.
# Before 0.19 the replay has no `modules`, and the GET is the only source.
# 0.20: optional module/catalog artwork and /server/module-icons/{digest}.
# 0.21: storage. GET /server/storage/volumes lists the server's own music
# folder, the drives and shares it mounted and the disks mounted under /media,
# /mnt or /run/media, each with a `summary` to show under its label;
# /queue/ws and /queue/events carry volumes_changed with the same list, and
# the replay state `volumes`. POST /server/storage/volumes/{id}/eject and
# /mount ask the root helper to unmount or mount one. GET
# /server/storage/folders?path= lists the folders in a path on the server's
# storage or under /home, or the places they can be in, for Settings to pick
# a music folder. GET /server/storage/location?entity_id= says where a Drives
# folder is and what a library makes of it (`holds`, `removable`), and POST
# /server/storage/adopt adds it to that library and /release takes out the
# source it is. Drives (source `drives`, `builtin`, `icon`, `count`) browses
# and plays every mounted volume from its files; its catalogs are `live` and
# `on_storage`, its root carries a folder `preview_config`, it lists
# `catalogs` only while a drive is mounted, and its rows carry the `icon` a
# client draws where they have no art.
# Settings saved through PUT /server/config reach the plugin that owns them.
# GET /server/version carries `storage`.
# 0.22: optional receiver inventory/commands, receivers_changed replay state,
# explicit receiver pairing requests/answers, opt-in password reveal,
# pairing mode and explicit saved-device removal.
# Also 0.22: plugin settings apply as they are saved. A module's on/off switch sets
# it up or shuts it down there and then, and any other change to a module's
# or device's settings reaches the plugin, which is set up again on them
# unless it takes them in itself; the module reports WARNING "Restarting…"
# meanwhile, through modules_changed, and then what it makes of its new
# settings. The PUT answers once the plugin has taken them in, or after five
# seconds while it still is. The Devices page no longer says a restart is
# needed. Each field and each collection of GET /server/config/schema carries
# `apply`: "instant" for most, "restart_required" for the few the server reads
# once at startup (port, interface, text embedding, streamer management,
# screen) and for a plugin field that turns on a feature whose packages install
# at the next start (AI search, generated album art), so a client restarts only
# for those; everything not so marked applies live.
# A save holding one of a plugin's restart_required fields is not applied
# live: it waits for that restart, which installs what the plugin then needs.
# schema_version moves when a plugin is set up again with a changed
# configuration model, appears or goes; a stale PUT draws its 409 as before.
# While a module is set up again, GET /content/{module}/… and the routes
# naming it answer 503 with Retry-After rather than 404, so a renderer retries;
# so does a module taken down for an update, and a save made meanwhile
# applies once it is back. A module whose update the installer never
# finished is listed ERROR with the reason until it is updated again or the
# server restarts.
# Also 0.22: where /server/version reports plugin_management.live_installation,
# POST /server/plugins/{id}/install, /update and /uninstall answer 202
# {"status": "applying", ...} and the server carries the operation out while
# it runs, loading the plugin itself; a release it cannot take into the
# running process answers "restarting" as before, decided before anything
# changes. GET /server/plugins/operation is the operation in flight or the
# last one, for a client to poll, reopened or not: {id, action, plugin_id,
# distribution, version, status: running|restarting|ok|failed, step,
# step_index, step_count, started_at, updated_at, finished_at, error}, or
# {"status": "idle"} when none ever ran; an install's steps are downloading,
# checking, installing_package, installing_environment and loading, an
# update's add preparing before installing_package, an uninstall's are
# preparing, checking and removing_package. GET /server/plugins'
# last_operation is the same record. An update stops that plugin's own
# playback while its files are replaced; the rest plays on.
# Also 0.22: a PUT /server/config to a module or device queues the optional
# packages the plugins need under the new settings, so whatever starts the
# server next installs them; GET /server/optional_packages marks them
# `pending`, and turning the feature off again takes them back out. The
# server's own start queues them too, except a plugin's whose install failed
# or was cut off at the last start. PUT /server/restart queues the same after what `install`
# names; a 400 for a key it refuses now queues nothing, and its `accepted`
# lists the keys it would have taken. A package any install found no wheel
# of for the server's Python and architecture is no longer queued for a
# plugin, nor are the other packages that plugin asks for with it, though
# `install` may still name it. A module's error_message ends with what a
# restart does for its `missing_packages`, or with why one cannot be
# installed here, and then `missing_packages` is empty. A plugin set up
# again or taken down while the server runs, by a save or a catalog
# operation, queues again as it goes, and what the page offers follows
# the plugins set up now.
# Also 0.22: Drives & shares. GET /server/storage/devices lists every drive and
# NFS share the server could read music from, mounted or not, with the actions
# that apply to each (`can_mount`, `can_unmount`, `can_eject`,
# `can_set_at_start`, `can_edit`, `can_forget`) and its Mount after restart
# switch (`at_start`, null where there is none; for one not kept yet, the
# switch keeping it would give it); a failed one carries `error`
# in plain words and `error_detail`, the mount's own, where Kalinka did not
# word it. `scan` says whether the search for shares on the network is
# running; asking keeps it running, POST /shares/scan asks every host again,
# and `mounting_available` is false where no mount helper is installed. POST
# /devices/{id}/mount and /unmount mount and unmount one now and answer once
# the helper has, or after 10 s: {id, state, error}, a mount `mounted`,
# `failed` with the reason or still `mounting`; an unmount the helper refuses
# answers 502 with its reason; a failed mount's answer carries
# `error_detail` too. A mount may carry the body of a PUT, applied as it
# mounts. A disk or a share not kept yet is kept once its mount succeeds, a
# USB drive only where the body changes something; one that fails is not
# kept, and is listed failed with `can_dismiss` until it is tried again,
# DELETE /devices/{id}/failure puts it away, or the server restarts. Neither
# a mount nor an unmount changes a switch the body does not. PUT /devices/{id} changes
# `at_start`, `label`, `read_only` or `version` where `can_edit`, keeping a
# device not kept and mounting nothing, and DELETE /devices/{id} forgets a
# kept one. POST
# /shares/probe asks a host for its exports, and POST /shares {host, export,
# version, at_start, read_only} mounts a share as asked, answering and
# keeping it as a mount does, or 409 where it is mounted already. Without the
# helper both mounts answer 503. A saved mount carries `at_start` and is
# mounted at start only with it on; saving one no longer mounts it. The
# settings schema no longer describes base_config.storage.mounts, and
# /server/version's `storage` has `devices`.
REST_API_VERSION = "0.22"


def get_rest_api_version() -> str:
    """Return the client-facing REST/WS API version (see :data:`REST_API_VERSION`)."""
    return REST_API_VERSION
